description:
Trouvez les différences entre 2 listes de caractères. Il s’agit des caractères présents dans une liste et pas 
dans l’autre, et réciproquement. Renvoyez la liste de ces éléments par ordre alphabétique. Attention, les 
listes peuvent contenir plusieurs fois les mêmes caractères. 
a = ["a","b","z","d","e","d"]; 
b = ["a","b", "j","j"]; 
diff(a, b)  ["d","e","j","z"]

Vous devez surveiller des installations industrielles dans le cercle arctique à l’aide de 1 à 16 caméras. En 
raison des coûts élevés des données, chaque commande envoyée à ces caméras est limitée à un octet. 
Chaque caméra dans chaque installation est initialement réglée à 30 degrés vers le bas (-30°) et pointée 
vers l'avant. Les caméras peuvent être commandées à distance pour les déplacer vers le haut (up) ou le 
bas (down), à gauche (left) ou à droite (right), jusqu'à 45 degrés maximum dans chacune des directions. 
'up' et 'right' sont considérés comme positifs, 'down' et 'left' sont considérés comme négatifs. 
Les quatre premiers bits du paquet représentent l’ID de la caméra (indexées à partir de 0). Le cinquième 
bit indique s’il faut déplacer la caméra de cinq degrés vers le haut, le sixième bit s’il faut baisser de cinq 
degrés.  Les  septième  et  huitième  bit  indiquent  s’il  faut  déplacer  la  caméra  à  gauche  ou  à  droite 
respectivement, de cinq degrés.  
Complétez ce début de programme : 
function Network (count) { 
  this.cameras = []; 
  59 
  for (var i = 0; i < count; i++) 
    this.cameras.push(new Camera(0, -30)); 
} 
Network.prototype.process = function (byte) { 
  // Ajustement de la caméra suivant la valeur de « byte » 
} 
function Camera (h, v) { 
  this.horizontal = h; 
  this.vertical = v; 
} 
Camera.prototype.move = function (h, v) { 
  // Ajustement de l’angle 
}

Déclarez et définissez une classe Vector qui représente un vecteur dans un espace tridimensionnel. Cette 
classe devrait avoir trois propriétés i, j et k. 
La classe Vector doit avoir un constructeur de classe qui accepte exactement trois arguments, tous requis, 
dans  l'ordre  suivant:  i,  j,  k,  et  attribuer  les  valeurs  des  arguments  aux  propriétés  publiques  i,  j  et  k 
respectivement.  Les  trois  arguments  sont  des  nombres  valides  (entiers  et    ou  décimaux)  mais  aucune 
vérification n'est requise de votre part. 
Définissez  une  méthode  publique getMagnitude qui  n'accepte  aucun  argument  et  renvoie la  norme  du  
vecteur. 
Les vecteurs unitaires dans les directions x, y et z sont communément désignés par i, j et k respectivement. 
Définissez trois méthodes publiques, statiques (c'est-à-dire directement appelées à partir de la classe elle-
  60 
même), getI, getJ et getK,  chacune sans    argument  et  renvoyant  des  vecteurs représentant  i,  j  et  k 
respectivement. 
Définissez également (voir exemples après) :  
• add(that) : addition de 2 vecteurs 
• multiplyByScalar(n) : multiplication par un scalaire 
• dot(that) : produit scalaire 
• cross(that) : produit vectoriel 
• isParallelTo(that) : est parallèle à... 
• isPerpendicularTo(that) : est perpendiculaire à... 
• normalize() : normalise le vecteur  
• isNormalized() : true ou false suivant que le vecteur est normalisé ou non. 
Exemples 
var v = new Vector(6, 10, -3); 
v.getMagnitude()  12.041594578792296 
var i = Vector.getI(); 
var j = Vector.getJ(); 
var k = Vector.getK(); 
console.log(i.i,i.j,i.k) 
 1 0 0 
console.log(j.i,j.j,j.k) 
 0 1 0 
console.log(k.i,k.j,k.k) 
 0 0 1 
var v = new Vector(3, 7 / 2, -3 / 2); 
var s = v.add(new Vector(-27, 3, 4)); 
console.log(s.i,s.j,s.k) 
 -24 6.5 2.5  
var v = new Vector(1 / 3, 177 / 27, -99); 
var e = v.multiplyByScalar(-3 / 7); 
console.log(e.i,e.j,e.k) 
 -0.14285714285714285 -2.8095238095238093 42.42857142857142 
var v = new Vector(-99 / 71, 22 / 23, 45) 
v.dot(new Vector(-5, 4, 7)  325.7979179 
var a = new Vector(2, 1, 3); 
var b = new Vector(4, 6, 5); 
var aCrossB = a.cross(b); 
console.log(aCrossB.i,aCrossB.j,aCrossB.k) 
 -13 2 8 
var a = new Vector(1045 / 23, -666 / 37, 15); 
var b = new Vector(161.3385037, -59124 / 925, 9854 / 185); 
a.isParallelTo(b)  true 
b.isParallelTo(a)  true 
var c = new Vector(-3, 0, 5); 
var d = new Vector(-12, 1, 20); 
c.isParallelTo(d)  false 
var a = new Vector(3, 4, 7); 
var b = new Vector(1 / 3, 2, -9 / 7); 
a.isPerpendicularTo(b)  true 
var c = new Vector(1, 3, 5); 
var d = new Vector(-2, -7, 4.4); 
c.isPerpendicularTo(d)  false 
var v = new Vector(-1, -1, 1); 
  61 
var u = v.normalize(); 
console.log(u.i,u.j,u.k) 
 -0.5773502691896258 -0.5773502691896258 0.5773502691896258 
var a = new Vector(-1 / Math.sqrt(2), 0, 1 / Math.sqrt(2)); 
var b = new Vector(1, 1, 1); 
a.isNormalized()  true 
b.isNormalized()  false

L’agence NSA veut espionner les conversations téléphoniques (appels ou SMS) et fait appel à vos services 
de programmeur. Pour ce faire, nous aurons besoin de définir des personnes (Person) ayant au moins les 
propriétés ou méthodes suivantes : name (pour le nom), call (appel) et text (SMS). La méthode call a 2 
paramètres, un objet téléphone contenant le propriétaire (owner) et le numéro (number) et la personne 
appelée. 
Par exemple 
var dan = new Person(\"Dan\"); 
var alex = new Person(\"Alex\"); 
var phone = {owner : dan, number: \"202-555-0199\"}; 
dan.call(phone, alex); 
Ici  2  personnes,  Dan  et  Alex,  un  téléphone  appartenant  à  Dan  et  Dan  appelle  Alex  avec  son  propre 
téléphone. 
La méthode text est très similaire à la méthode call, mais au lieu d’avoir un unique destinataire, il peut y 
en avoir un nombre quelconque (tous étant des personnes). 
Exemple 
var mark = new Person (\"Mark\"); 
dan.text (phone, alex, mark); 
Dan envoie un SMS à Alex et Mark avec son propre téléphone. 
La NSA vous oblige à enregistrer chaque appel téléphonique et chaque SMS que chaque personne a émis. 
L'objet  NSA  aura  une  méthode log.  Cette  méthode  prend  un  paramètre  :  une  instance  de Person.  Il 
renverra le journal conservé sur cette personne dans le format suivant : 
[CALLER] called/texted [CALLEE] from [PHONE OWNER]'s phone([PHONE NUMBER]) 
Chaque enregistrement sera séparé par \
.  
Dan called Erin from Dan's phone(202-555-0149) 
Dan texted Anthony from Anthony's phone(202-555-0199) 
Dan texted Alex from Dan's phone(202-555-0149) 
S'il n'y a pas d'entrées pour la personne, la méthode renverra simplement « No Entries ». 
La NSA ayant peur d’être accusée d'avoir espionné des civils, assurez-vous d'effacer chaque enregistrement 
individuel après l’avoir lu dans le journal.  
Exemple complet 
  62 
var dan = new Person(\"Dan\"); 
var mark = new Person(\"Mark\"); 
var phone = {owner: dan, number: '202-555-0199'}; 
dan.call(phone, mark);  
NSA.log(dan)  'Dan called Mark from Dan\\'s phone(202-555-0199)' 
var anthony = new Person(\"Anthony\"); 
anthony.call(phone,dan) 
NSA.log(anthony)  'Anthony called Dan from Dan\\'s phone(202-555-0199)' 
var mobile = {owner: mark, number: '202-555-0166'}; 
mark.text(mobile,dan,anthony) 
mark.call(phone,anthony) 
NSA.log(mark)   
'Mark texted Dan from Mark\\'s phone(202-555-0166) 
 Mark texted Anthony from Mark\\'s phone(202-555-0166) 
 Mark called Anthony from Dan\\'s phone(202-555-0166) 
' 
var erin = new Person(\"Erin\"); 
NSA.log(erin)  'No Entries' 
Structure de votre programme 
// Objet NSA  
var NSA = {}; 
// Constructeur de personnes 
var Person = function() {  
  this.name; 
  this.call = function(cellphone, callee) { 
  } 
  this.text = function(cellphone) {  
  } 
}

Grace au code ci-dessous (à copier-coller), nous pouvons construire des matrices à 2 dimensions infinies 
où chaque élément est false sauf celui aux coordonnées n, m. Écrivez une fonction qui prend une telle 
matrice et renvoie la paire d'indices où la matrice est true. 
const generate = (m,n)=>{ 
  var hithandler = { 
    get: (_,col)=>col==n?true:false, 
    set: ()=>false 
  } 
  var misshandler = { 
    get: ()=>false, set: ()=>false 
  } 
  var hit = new Proxy({}, hithandler); 
  var miss = new Proxy({}, misshandler); 
  var rowhandler = { 
    get: (_,row)=>row==m?hit:miss, 
    set: ()=>false 
  }; 
  var p = new Proxy({}, rowhandler); 
  return p; 
} 
  63 
Vous pouvez utiliser mat[j][i] normalement pour accéder aux éléments  qui seront tous faux, sauf lorsque 
j = m et i = n. Cependant, les proxies se comportent tout à fait différemment des tableaux, de sorte que 
les méthodes standards ne fonctionneront pas. 
var mat = generate(0,10) 
findTrue(mat)  [0,10]
